(4540022, 653571, 32837, '<td valign="top">Going for the brown?</td>', 'Going for the brown?', '2008-03-05 08:48:17.000000', NULL, 1),
(4540023, 653777, 32837, '<td valign="top">Huh? What is it?</td>', 'Huh? What is it?', '2008-03-05 08:48:52.000000', NULL, 1),
(4540027, 652588, 88923, '<td valign="top">Good idea.  I think the silverware in focus and the cup out of focus gives it a nice effect.</td>', 'Good idea.  I think the silverware in focus and the cup out of focus gives it a nice effect.', '2008-03-05 08:50:31.000000', NULL, 1),
(4540028, 654547, 88923, '<td valign="top">Great idea and you did well with it and a difficult one to put together, I''m sure.</td>', 'Great idea and you did well with it and a difficult one to put together, I''m sure.', '2008-03-05 08:51:35.000000', NULL, 1),
(4540029, 654275, 32837, '<td valign="top">cool lighting</td>', 'cool lighting', '2008-03-05 08:52:00.000000', NULL, 1),
(4540034, 653967, 32837, '<td valign="top">original</td>', 'original', '2008-03-05 08:53:36.000000', NULL, 1),
(4540040, 654399, 32837, '<td valign="top">Nice lighting</td>', 'Nice lighting', '2008-03-05 08:55:56.000000', NULL, 1),
(4540049, 654728, 38496, '<td valign="top">not a fan of the red border, but the chocolate looks great!</td>', 'not a fan of the red border, but the chocolate looks great!', '2008-03-05 08:59:27.000000', NULL, 1),
(4540055, 653536, 58457, '<td valign="top">I think the lighting is nice, but I just don''t "get it".  Why is he eating glass?  I guess I''m kinda missing the context.</td>', 'I think the lighting is nice, but I just don''t "get it".  Why is he eating glass?  I guess I''m kinda missing the context.', '2008-03-05 09:01:11.000000', NULL, 1),
(4540061, 653476, 58457, '<td valign="top">I don''t think you''ll score super high, but you could kind run with the shoe horn theme for a series of photos...  Kinda funny!</td>', 'I don''t think you''ll score super high, but you could kind run with the shoe horn theme for a series of photos...  Kinda funny!', '2008-03-05 09:01:56.000000', NULL, 1),
(4540065, 652554, 58457, '<td valign="top">This could maybe be cropped a bit tighter... Currently it comes off a bit dull.</td>', 'This could maybe be cropped a bit tighter... Currently it comes off a bit dull.', '2008-03-05 09:02:38.000000', NULL, 1),
(4540068, 654363, 58457, '<td valign="top">At first I didn''t even see that the water was splashing on a foreground fork!  I thought I was looking into a tub of water.</td>', 'At first I didn''t even see that the water was splashing on a foreground fork!  I thought I was looking into a tub of water.', '2008-03-05 09:03:47.000000', NULL, 1),
(4540069, 653760, 58457, '<td valign="top">mmm... not really silverware....</td>', 'mmm... not really silverware....', '2008-03-05 09:04:54.000000', NULL, 1),
(4540074, 654687, 58457, '<td valign="top">I think this idea of anthropomorphic forks is a good one, but the execution makes it a bit hard to see whats going on... I''m wondering how it looked in color.</td>', 'I think this idea of anthropomorphic forks is a good one, but the execution makes it a bit hard to see whats going on... I''m wondering how it looked in color.', '2008-03-05 09:07:25.000000', NULL, 1),
(4540076, 654712, 58457, '<td valign="top">Or is it a Forkpion?</td>', 'Or is it a Forkpion?', '2008-03-05 09:08:54.000000', NULL, 1),
(4540082, 652876, 58457, '<td valign="top">Very simple, yet I think an effective composition</td>', 'Very simple, yet I think an effective composition', '2008-03-05 09:10:41.000000', NULL, 1),
(4540086, 654709, 58457, '<td valign="top">the control you have over the light is nice.  It almost looks like a 3D computer rendering.</td>', 'the control you have over the light is nice.  It almost looks like a 3D computer rendering.', '2008-03-05 09:11:46.000000', NULL, 1),
(4540088, 653772, 58457, '<td valign="top">ba dum bum!</td>', 'ba dum bum!', '2008-03-05 09:12:12.000000', NULL, 1),
(4540090, 654604, 58457, '<td valign="top">I kinda wish the right hand tine was touching the surface/shadow...</td>', 'I kinda wish the right hand tine was touching the surface/shadow...', '2008-03-05 09:13:52.000000', NULL, 1),
(4540096, 654283, 77425, '<td valign="top">not a good angle for this shot, it just looks the the horizontal spoon is sitting on the table above the other spoon.</td>', 'not a good angle for this shot, it just looks the the horizontal spoon is sitting on the table above the other spoon.', '2008-03-05 09:15:27.000000', NULL, 1),
(4540121, 654518, 58457, '<td valign="top">ah, this is clever... did you light the fork from behind the paper?</td>', 'ah, this is clever... did you light the fork from behind the paper?', '2008-03-05 09:23:17.000000', NULL, 1),
(4540122, 653281, 58457, '<td valign="top">The drip makes this still life a bit more unique...</td>', 'The drip makes this still life a bit more unique...', '2008-03-05 09:23:59.000000', NULL, 1),
(4540124, 654373, 58457, '<td valign="top">idea wise, this is hilarious...  the execution leaves a bit to be desired...</td>', 'idea wise, this is hilarious...  the execution leaves a bit to be desired...', '2008-03-05 09:24:35.000000', NULL, 1),
(4540126, 654669, 58457, '<td valign="top">This really is nice....  good composition, and execution!</td>', 'This really is nice....  good composition, and execution!', '2008-03-05 09:25:18.000000', NULL, 1),
(4540128, 654670, 58457, '<td valign="top">almost a surrealistic photo.  I like it!</td>', 'almost a surrealistic photo.  I like it!', '2008-03-05 09:25:39.000000', NULL, 1),
(4540132, 654371, 58457, '<td valign="top">I like the beading under the spoon...</td>', 'I like the beading under the spoon...', '2008-03-05 09:27:35.000000', NULL, 1),
(4540136, 654268, 58457, '<td valign="top">Interesting use of reflections to create a more abstract look...</td>', 'Interesting use of reflections to create a more abstract look...', '2008-03-05 09:28:34.000000', NULL, 1),
(4540154, 654246, 90495, '<td valign="top">It gave me a laugh. That shadow takes away from the overall quality of the shot and it may be a little underexposed.</td>', 'It gave me a laugh. That shadow takes away from the overall quality of the shot and it may be a little underexposed.', '2008-03-05 09:38:49.000000', NULL, 1),
(4540182, 654688, 58457, '<td valign="top">hmmm... clever title...  i''m curious about the execution...fishing line?</td>', 'hmmm... clever title...  i''m curious about the execution...fishing line?', '2008-03-05 09:51:37.000000', NULL, 1),
(4540204, 654295, 58457, '<td valign="top">sacrificing the dinnerware for a challenge... nice! good composition and idea.</td>', 'sacrificing the dinnerware for a challenge... nice! good composition and idea.', '2008-03-05 09:57:25.000000', NULL, 1),
(4540213, 653560, 58457, '<td valign="top">from the reflection--were you holding the camera in your hand?  A tripod may have helped your sharpness.  Plus, maybe higher contrast in post processing would have helped.</td>', 'from the reflection--were you holding the camera in your hand?  A tripod may have helped your sharpness.  Plus, maybe higher contrast in post processing would have helped.', '2008-03-05 10:00:10.000000', NULL, 1),
(4540225, 652720, 58457, '<td valign="top">I''m not sure how I feel about the cotton background... It seems to almost take away a bit from the apple, fork, and blue thingy...  especially because they are such definitive shapes.</td>', 'I''m not sure how I feel about the cotton background... It seems to almost take away a bit from the apple, fork, and blue thingy...  especially because they are such definitive shapes.', '2008-03-05 10:03:48.000000', NULL, 1),
(4540227, 654317, 58457, '<td valign="top">Very strong composition and entry!  Great execution.</td>', 'Very strong composition and entry!  Great execution.', '2008-03-05 10:04:36.000000', NULL, 1),
(4540230, 654478, 58457, '<td valign="top">This is a nice strong photograph...  Simple composition coupled with good execution...</td>', 'This is a nice strong photograph...  Simple composition coupled with good execution...', '2008-03-05 10:05:43.000000', NULL, 1),
(4540231, 653648, 72894, '<td valign="top">I like this but found it to be a bit confusing esthetically. The background reflections are a distraction to me.</td>', 'I like this but found it to be a bit confusing esthetically. The background reflections are a distraction to me.', '2008-03-05 10:05:47.000000', NULL, 1),
(4540235, 654784, 58457, '<td valign="top">I think you should contact the person who did the forks in a similar fashion to yours--they ended up with stronger execution with a similar idea.</td>', 'I think you should contact the person who did the forks in a similar fashion to yours--they ended up with stronger execution with a similar idea.', '2008-03-05 10:07:45.000000', NULL, 1),
(4540251, 652909, 58457, '<td valign="top">hmmm, another one similar to this, I think your''s may be stronger... I''ll have to think on it...</td>', 'hmmm, another one similar to this, I think your''s may be stronger... I''ll have to think on it...', '2008-03-05 10:15:21.000000', NULL, 1),
(4540253, 653508, 90256, '<td valign="top">The window light is really distracting to me.</td>', 'The window light is really distracting to me.', '2008-03-05 10:16:28.000000', NULL, 1),
(4540256, 654041, 58457, '<td valign="top">By adding the cough drop you made this more interesting.  Others very similar to this in the challenge, but I definitely like the color--it reminds me of a royal crest or crown or something along that line.</td>', 'By adding the cough drop you made this more interesting.  Others very similar to this in the challenge, but I definitely like the color--it reminds me of a royal crest or crown or something along that line.', '2008-03-05 10:16:50.000000', NULL, 1),
(4540258, 653768, 90217, '<td valign="top">to blury</td>', 'to blury', '2008-03-05 10:17:13.000000', NULL, 1),
(4540273, 652588, 73981, '<td valign="top">This would''ve worked well in the "Framed" challenge. I like it!!</td>', 'This would''ve worked well in the "Framed" challenge. I like it!!', '2008-03-05 10:20:31.000000', NULL, 1),
(4540275, 654698, 68546, '<td valign="top">excellent set up! I like the composition but i''m not sure the lighting is enough to really bring the shot out. For example the spoons and fork above the plate are very dark. Plus the wine glass top left looks very odd at the angle you shot from. The shot has a nice feel to it though</td>', 'excellent set up! I like the composition but i''m not sure the lighting is enough to really bring the shot out. For example the spoons and fork above the plate are very dark. Plus the wine glass top left looks very odd at the angle you shot from. The shot has a nice feel to it though', '2008-03-05 10:21:16.000000', NULL, 1),
(4540280, 654531, 68546, '<td valign="top">one of the better "Fork in the Road" entries.</td>', 'one of the better "Fork in the Road" entries.', '2008-03-05 10:22:52.000000', NULL, 1),
(4540282, 653760, 90256, '<td valign="top">I could have used one of those eating my steak last night!</td>', 'I could have used one of those eating my steak last night!', '2008-03-05 10:23:06.000000', NULL, 1),
(4540283, 654569, 90286, '<td valign="top">i think it could have been more intersting if it was cropped differently.</td>', 'i think it could have been more intersting if it was cropped differently.', '2008-03-05 10:23:21.000000', NULL, 1),
(4540289, 654698, 73981, '<td valign="top">And to think you''d not use (And by you, I mean me) any of those utensils to eat that...it would go from hand to mouth to stomach in a matter of seconds. YUMMY!! 8</td>', 'And to think you''d not use (And by you, I mean me) any of those utensils to eat that...it would go from hand to mouth to stomach in a matter of seconds. YUMMY!! 8', '2008-03-05 10:24:37.000000', NULL, 1),
(4540292, 653760, 90223, '<td valign="top">silverware?.............</td>', 'silverware?.............', '2008-03-05 10:25:30.000000', NULL, 1),
(4540303, 654218, 90286, '<td valign="top">the sharp edge around the pear is all i can seeee.</td>', 'the sharp edge around the pear is all i can seeee.', '2008-03-05 10:27:52.000000', NULL, 1),
(4540305, 653760, 90545, '<td valign="top">good picture, wrong catagory?</td>', 'good picture, wrong catagory?', '2008-03-05 10:28:34.000000', NULL, 1),
(4540326, 653913, 3102, '<td valign="top">This probably would have been a cool shot had it been big enough to view.  But it''s only about half the size of what''s allowed.</td>', 'This probably would have been a cool shot had it been big enough to view.  But it''s only about half the size of what''s allowed.', '2008-03-05 10:32:36.000000', NULL, 1),
(4540330, 654685, 73981, '<td valign="top">Is this Thai food? I love Thai food...not going to stay this looks tasty until I know it''s Thai food...until then, it''s just a nice photo. 7</td>', 'Is this Thai food? I love Thai food...not going to stay this looks tasty until I know it''s Thai food...until then, it''s just a nice photo. 7', '2008-03-05 10:33:11.000000', NULL, 1),
(4540335, 654363, 72894, '<td valign="top">I like  this but find the background to be distracting.</td>', 'I like  this but find the background to be distracting.', '2008-03-05 10:33:58.000000', NULL, 1),
(4540339, 654688, 73981, '<td valign="top">Interesting...to say the least. I am guessing some kind of string lifting it up, but I''m looking forward to the answer after the challenge. Nice job.</td>', 'Interesting...to say the least. I am guessing some kind of string lifting it up, but I''m looking forward to the answer after the challenge. Nice job.', '2008-03-05 10:35:42.000000', NULL, 1),
(4540361, 654531, 73981, '<td valign="top">I would''ve lowered the camera and gotten in closer to the fork. Not enough of it is part of the image IMO.</td>', 'I would''ve lowered the camera and gotten in closer to the fork. Not enough of it is part of the image IMO.', '2008-03-05 10:41:59.000000', NULL, 1),
(4540377, 654334, 35947, '<td valign="top">Excellent shot!  I love how clean and almost abstract it looks, and the square frame really works here!</td>', 'Excellent shot!  I love how clean and almost abstract it looks, and the square frame really works here!', '2008-03-05 10:46:08.000000', NULL, 1),
(4540384, 654569, 35947, '<td valign="top">Good focus, abstact feel, well executed but IMHO it doesn''t hold my attention for long.</td>', 'Good focus, abstact feel, well executed but IMHO it doesn''t hold my attention for long.', '2008-03-05 10:47:17.000000', NULL, 1),
(4540390, 654373, 35947, '<td valign="top">Funny and creative image!</td>', 'Funny and creative image!', '2008-03-05 10:48:31.000000', NULL, 1),
