(4540401, 654544, 35947, '<td valign="top">I like this.  Well executed and very unique/creative silverware in artful pose.</td>', 'I like this.  Well executed and very unique/creative silverware in artful pose.', '2008-03-05 10:50:22.000000', NULL, 1),
