(4540888, 653337, 35947, '<td valign="top">Love the funky colors/shape in the background but wish the focus was a little sharper on the forks.</td>', 'Love the funky colors/shape in the background but wish the focus was a little sharper on the forks.', '2008-03-05 13:46:23.000000', NULL, 1),
(4540891, 654687, 90658, '<td valign="top">If I came across this as a print in a shop or gallery, I''d spend quite a bit of time attempting to figure out what was going on.  So much so, I would lose the pleasure of the initial visiual.  It''s a good thing that it is part of a silverware "collection" to give me the clues needed.</td>', 'If I came across this as a print in a shop or gallery, I''d spend quite a bit of time attempting to figure out what was going on.  So much so, I would lose the pleasure of the initial visiual.  It''s a good thing that it is part of a silverware "collection" to give me the clues needed.', '2008-03-05 13:46:54.000000', NULL, 1),
(4540892, 654720, 35947, '<td valign="top">Nice lines/angles.</td>', 'Nice lines/angles.', '2008-03-05 13:46:56.000000', NULL, 1),
(4540896, 653648, 35947, '<td valign="top">Lots of leading lines here with the reflections and chairs (???) in the back ground making more lined reflections.  A little busy but still works.</td>', 'Lots of leading lines here with the reflections and chairs (???) in the back ground making more lined reflections.  A little busy but still works.', '2008-03-05 13:48:14.000000', NULL, 1),
