(4541161, 653751, 70107, '<td valign="top">Is there a filter over this?<br/>Some sort of grunge layer applied in overlay?<br/>I would love to know how you did this with basic editing rules</td>', 'Is there a filter over this?Some sort of grunge layer applied in overlay?I would love to know how you did this with basic editing rules', '2008-03-05 15:24:52.000000', NULL, 1),
(4541162, 652588, 83569, '<td valign="top">Love the idea! Cool point of view... sort of like a lineup at a police station with the detective looking over. Love it!</td>', 'Love the idea! Cool point of view... sort of like a lineup at a police station with the detective looking over. Love it!', '2008-03-05 15:24:56.000000', NULL, 1),
(4541164, 654532, 83569, '<td valign="top">Did you make this yourself? Very cool idea. I just wish it was a tad bit sharper.</td>', 'Did you make this yourself? Very cool idea. I just wish it was a tad bit sharper.', '2008-03-05 15:25:40.000000', NULL, 1),
(4541169, 654687, 83569, '<td valign="top">Very interesting. I love how even though the fork is no longer in perfect form, it still looks delicate yet mechanical.</td>', 'Very interesting. I love how even though the fork is no longer in perfect form, it still looks delicate yet mechanical.', '2008-03-05 15:27:39.000000', NULL, 1),
(4541175, 654249, 90518, '<td valign="top">cute idea :)</td>', 'cute idea :)', '2008-03-05 15:31:28.000000', NULL, 1),
(4541182, 654483, 90518, '<td valign="top">hehe cute! wish more of the image was in focus though</td>', 'hehe cute! wish more of the image was in focus though', '2008-03-05 15:33:03.000000', NULL, 1),
(4541185, 654518, 90518, '<td valign="top">how the...?!</td>', 'how the...?!', '2008-03-05 15:34:20.000000', NULL, 1),
(4541256, 653656, 3087, '<td valign="top">Nice composition, and it''s not easy to create one that doesn''t just look forced or cluttered. Nice lighting too and I like your DOF choice.</td>', 'Nice composition, and it''s not easy to create one that doesn''t just look forced or cluttered. Nice lighting too and I like your DOF choice.', '2008-03-05 16:02:09.000000', NULL, 1),
(4541258, 654772, 3087, '<td valign="top">Nice though I''d prefer it as a portrait orientation allowing more space above the spoon and corn pops (they feel too close to the top edge to me) whilst still giving space for the drops below.</td>', 'Nice though I''d prefer it as a portrait orientation allowing more space above the spoon and corn pops (they feel too close to the top edge to me) whilst still giving space for the drops below.', '2008-03-05 16:02:52.000000', NULL, 1),
(4541260, 654099, 72894, '<td valign="top">Wonderful !</td>', 'Wonderful !', '2008-03-05 16:04:27.000000', NULL, 1),
(4541261, 653336, 72894, '<td valign="top">I love the lighting..</td>', 'I love the lighting..', '2008-03-05 16:04:37.000000', NULL, 1),
(4541263, 654320, 3087, '<td valign="top">Interesting subjects and interesting detail with warm lighting and lovely shallow DOF. The lower edge feels crowded, could do with some negative space like you have at the top.</td>', 'Interesting subjects and interesting detail with warm lighting and lovely shallow DOF. The lower edge feels crowded, could do with some negative space like you have at the top.', '2008-03-05 16:05:13.000000', NULL, 1),
(4541265, 654536, 3087, '<td valign="top">Lovely and simple. I like the reflection of the curves of the fork in the curve of the bowl.</td>', 'Lovely and simple. I like the reflection of the curves of the fork in the curve of the bowl.', '2008-03-05 16:05:42.000000', NULL, 1),
(4541266, 654045, 3087, '<td valign="top">Beautiful subject matter, really strong composition, lovely lighting and nicely shallow DOF. Works for me!</td>', 'Beautiful subject matter, really strong composition, lovely lighting and nicely shallow DOF. Works for me!', '2008-03-05 16:06:18.000000', NULL, 1),
(4541267, 654719, 3087, '<td valign="top">How surreal! I like it! Not keen on the background though.</td>', 'How surreal! I like it! Not keen on the background though.', '2008-03-05 16:06:54.000000', NULL, 1),
(4541268, 654364, 26001, '<td valign="top">excellent abstract shot. even the tone works really well 8</td>', 'excellent abstract shot. even the tone works really well 8', '2008-03-05 16:07:46.000000', NULL, 1),
(4541269, 653395, 3087, '<td valign="top">Beautiful! I love the light, I love the textures, I love the shallow DOF.</td>', 'Beautiful! I love the light, I love the textures, I love the shallow DOF.', '2008-03-05 16:09:56.000000', NULL, 1),
(4541270, 654512, 3087, '<td valign="top">What an intriguing still life. The shadow on the vase has such sensual curves given the straight rod of the real fork handle. I like the texture and pattern and detail added by the dried leaves.</td>', 'What an intriguing still life. The shadow on the vase has such sensual curves given the straight rod of the real fork handle. I like the texture and pattern and detail added by the dried leaves.', '2008-03-05 16:10:43.000000', NULL, 1),
(4541271, 652588, 3087, '<td valign="top">Cute idea. Perhaps stronger as a portrait losing a large slice from both left and right.</td>', 'Cute idea. Perhaps stronger as a portrait losing a large slice from both left and right.', '2008-03-05 16:11:20.000000', NULL, 1),
(4541292, 652876, 35947, '<td valign="top">Great lines, clean and simple.  9</td>', 'Great lines, clean and simple.  9', '2008-03-05 16:26:03.000000', NULL, 1),
(4541293, 653697, 35947, '<td valign="top">Smooth and clean.  Very nice!</td>', 'Smooth and clean.  Very nice!', '2008-03-05 16:27:14.000000', NULL, 1),
(4541295, 653951, 89341, '<td valign="top">I think this would benefit from some post processing, just simple adjusting the brightness / contrast, auto levels drops the background down to a much darker black without loosing the spoons ... also applying an unsharp mask crispens up the image</td>', 'I think this would benefit from some post processing, just simple adjusting the brightness / contrast, auto levels drops the background down to a much darker black without loosing the spoons ... also applying an unsharp mask crispens up the image', '2008-03-05 16:27:30.000000', NULL, 1),
(4541296, 653696, 35947, '<td valign="top">Funky looking ice cube!  Nice DOF and composite.</td>', 'Funky looking ice cube!  Nice DOF and composite.', '2008-03-05 16:27:52.000000', NULL, 1),
(4541298, 654045, 35947, '<td valign="top">Square crop works great here.  The composition, focus, and DOF is spot on.  Excellent work!</td>', 'Square crop works great here.  The composition, focus, and DOF is spot on.  Excellent work!', '2008-03-05 16:28:57.000000', NULL, 1),
(4541300, 653224, 89341, '<td valign="top">Excellent shot, works really well</td>', 'Excellent shot, works really well', '2008-03-05 16:29:43.000000', NULL, 1),
(4541301, 652842, 35947, '<td valign="top">Very creative and unique!</td>', 'Very creative and unique!', '2008-03-05 16:29:51.000000', NULL, 1),
(4541308, 654523, 89341, '<td valign="top">Nice shot</td>', 'Nice shot', '2008-03-05 16:32:03.000000', NULL, 1),
(4541317, 654698, 89341, '<td valign="top">I think there is a little too much in the picture though. Personally I''d loose the candles and the napkins IMHO. Despite that I do like the set up so doesn''t loose too much</td>', 'I think there is a little too much in the picture though. Personally I''d loose the candles and the napkins IMHO. Despite that I do like the set up so doesn''t loose too much', '2008-03-05 16:36:43.000000', NULL, 1),
(4541319, 654249, 89341, '<td valign="top">Ha ha, funny idea</td>', 'Ha ha, funny idea', '2008-03-05 16:37:24.000000', NULL, 1),
(4541326, 654569, 89341, '<td valign="top">I like the detail on the knife ... personally I''d prefer just a little bit more  of the knife in the picture</td>', 'I like the detail on the knife ... personally I''d prefer just a little bit more  of the knife in the picture', '2008-03-05 16:39:23.000000', NULL, 1),
(4541328, 653772, 19841, '<td valign="top">Good idea, poor execution.  More attention to the background would have helped.</td>', 'Good idea, poor execution.  More attention to the background would have helped.', '2008-03-05 16:41:03.000000', NULL, 1),
(4541337, 652909, 89341, '<td valign="top">Very clever</td>', 'Very clever', '2008-03-05 16:47:35.000000', NULL, 1),
(4541339, 654364, 19841, '<td valign="top">More depth of field would have helped immensely.</td>', 'More depth of field would have helped immensely.', '2008-03-05 16:49:52.000000', NULL, 1),
(4541340, 652842, 89341, '<td valign="top">Clever idea, works well</td>', 'Clever idea, works well', '2008-03-05 16:50:33.000000', NULL, 1),
(4541347, 653773, 89341, '<td valign="top">Nice idea, I like it, shame about the strings still showing (I know you cant remove them in basic) ... maybe a darker background?</td>', 'Nice idea, I like it, shame about the strings still showing (I know you cant remove them in basic) ... maybe a darker background?', '2008-03-05 16:53:12.000000', NULL, 1),
(4541348, 654268, 89341, '<td valign="top">I like the reflections</td>', 'I like the reflections', '2008-03-05 16:53:53.000000', NULL, 1),
(4541353, 652547, 89341, '<td valign="top">The colours work very well, the shininess is excellent ... shame about the reflection in the bottom of the spoon ... doesn''t detract much though</td>', 'The colours work very well, the shininess is excellent ... shame about the reflection in the bottom of the spoon ... doesn''t detract much though', '2008-03-05 16:56:17.000000', NULL, 1),
(4541356, 652581, 88352, '<td valign="top">... and Winnie The Pooh bandages... lol.  Very creative.</td>', '... and Winnie The Pooh bandages... lol.  Very creative.', '2008-03-05 16:57:00.000000', NULL, 1),
(4541359, 653777, 89341, '<td valign="top">Not really knife fork or spoon so doesn''t quite fit IMHO, sorry</td>', 'Not really knife fork or spoon so doesn''t quite fit IMHO, sorry', '2008-03-05 16:57:37.000000', NULL, 1),
(4541361, 652876, 89341, '<td valign="top">don''t forget a title</td>', 'don''t forget a title', '2008-03-05 16:59:06.000000', NULL, 1),
(4541372, 652588, 89341, '<td valign="top">I like the framing, maybe I''d have cropped more to make the kfs larger</td>', 'I like the framing, maybe I''d have cropped more to make the kfs larger', '2008-03-05 17:02:54.000000', NULL, 1),
(4541391, 653336, 41337, '<td valign="top"><b>Positives:</b> The splash has impact and it''s got good color.  <br/> <br/><b>Negatives:</b> Lighting isn''t that special (just ok) and it looks way over sharpened or over contrasted. It could also be due to the lighting which is just too harsh which ruins the fluidity of the water, if that makes sense. In addition, the background wrinkles shouldn''t exist in a setup shot like this. Makes it look amateurish.</td>', 'Positives: The splash has impact and it''s got good color.   Negatives: Lighting isn''t that special (just ok) and it looks way over sharpened or over contrasted. It could also be due to the lighting which is just too harsh which ruins the fluidity of the water, if that makes sense. In addition, the background wrinkles shouldn''t exist in a setup shot like this. Makes it look amateurish.', '2008-03-05 17:13:24.000000', NULL, 1),
(4541394, 654544, 41337, '<td valign="top">Artistic. Beautiful tones. Nicely rendered.</td>', 'Artistic. Beautiful tones. Nicely rendered.', '2008-03-05 17:15:09.000000', NULL, 1),
(4541395, 653777, 60383, '<td valign="top">Get your brain back in the box. ;p</td>', 'Get your brain back in the box. ;p', '2008-03-05 17:17:21.000000', NULL, 1),
(4541420, 652909, 86799, '<td valign="top">Cool idea, well executed.</td>', 'Cool idea, well executed.', '2008-03-05 17:33:14.000000', NULL, 1),
(4541428, 653697, 86799, '<td valign="top">All silverware is created equal.  Do you mean some is just more equal than others?  Nice, smooth image, just the right tones.</td>', 'All silverware is created equal.  Do you mean some is just more equal than others?  Nice, smooth image, just the right tones.', '2008-03-05 17:36:21.000000', NULL, 1),
(4541506, 652842, 43774, '<td valign="top">Different and creative, I like it!</td>', 'Different and creative, I like it!', '2008-03-05 18:10:19.000000', NULL, 1),
(4541507, 652589, 43774, '<td valign="top">Creative and surreal, good job</td>', 'Creative and surreal, good job', '2008-03-05 18:10:31.000000', NULL, 1),
(4541508, 654203, 43774, '<td valign="top">Love the look of the smoke beneath the spoon, well done.</td>', 'Love the look of the smoke beneath the spoon, well done.', '2008-03-05 18:10:45.000000', NULL, 1),
(4541510, 654364, 43774, '<td valign="top">Excellent DOF and tones</td>', 'Excellent DOF and tones', '2008-03-05 18:10:57.000000', NULL, 1),
(4541511, 654111, 43774, '<td valign="top">Nice colours, good exposure and clarity</td>', 'Nice colours, good exposure and clarity', '2008-03-05 18:11:14.000000', NULL, 1),
(4541512, 654478, 43774, '<td valign="top">Simple, effective</td>', 'Simple, effective', '2008-03-05 18:11:23.000000', NULL, 1),
(4541513, 654652, 43774, '<td valign="top">Very cute</td>', 'Very cute', '2008-03-05 18:11:33.000000', NULL, 1),
(4541584, 654364, 89424, '<td valign="top">This photograph has a lot of lines and rhythm. There is also a good amount of movement.</td>', 'This photograph has a lot of lines and rhythm. There is also a good amount of movement.', '2008-03-05 18:49:12.000000', NULL, 1),
(4541588, 653918, 89424, '<td valign="top">This forms of the forks in this photograph really balance the photo out.</td>', 'This forms of the forks in this photograph really balance the photo out.', '2008-03-05 18:50:15.000000', NULL, 1),
(4541590, 653571, 41337, '<td valign="top">Was this taken at Sporktopia located somewhere in the Lyra Constellation?</td>', 'Was this taken at Sporktopia located somewhere in the Lyra Constellation?', '2008-03-05 18:50:51.000000', NULL, 1),
(4541591, 652354, 89424, '<td valign="top">The lighting in this picture is very harsh. The reflection on the forks are distracting.</td>', 'The lighting in this picture is very harsh. The reflection on the forks are distracting.', '2008-03-05 18:50:53.000000', NULL, 1),
(4541595, 654209, 89424, '<td valign="top">This photograph is strong because of the contrast. Also the lines in the background add rhythm.</td>', 'This photograph is strong because of the contrast. Also the lines in the background add rhythm.', '2008-03-05 18:52:06.000000', NULL, 1),
(4541599, 654052, 89424, '<td valign="top">There aren''t many values in this photograph but the concentric circles lead the eye around the picture.</td>', 'There aren''t many values in this photograph but the concentric circles lead the eye around the picture.', '2008-03-05 18:53:16.000000', NULL, 1),
(4541603, 654232, 41337, '<td valign="top">Positives: Good concept and composition. <br/> <br/>Negatives: Lighting isn''t good. It''s too harsh. Bounced/diffused light would have been better.</td>', 'Positives: Good concept and composition.  Negatives: Lighting isn''t good. It''s too harsh. Bounced/diffused light would have been better.', '2008-03-05 18:55:16.000000', NULL, 1),
(4541604, 654327, 89424, '<td valign="top">This photograph has a little to many shadows and hot spots. The cropping in this picture is awkward.</td>', 'This photograph has a little to many shadows and hot spots. The cropping in this picture is awkward.', '2008-03-05 18:55:19.000000', NULL, 1),
(4541619, 653693, 41337, '<td valign="top">Funny concept and well executed for basic editing. The only negative I have is how you positioned the cutting board. It hurts the composition. It would have made more sense to have the edge of the board level with the bottom frame so you didn''t have the gap there plus it would have eliminated the feeling of everything floating in the air.</td>', 'Funny concept and well executed for basic editing. The only negative I have is how you positioned the cutting board. It hurts the composition. It would have made more sense to have the edge of the board level with the bottom frame so you didn''t have the gap there plus it would have eliminated the feeling of everything floating in the air.', '2008-03-05 19:03:15.000000', NULL, 1),
(4541633, 654669, 41337, '<td valign="top">Very nice. The lighting is good, just a little blown in some spots but nothing major. I also like the slight curve the surface provides in the composition. The fire could be better though. It''s too ridged. If it had a little wave to it that would have complimented the surface curvature nicely.</td>', 'Very nice. The lighting is good, just a little blown in some spots but nothing major. I also like the slight curve the surface provides in the composition. The fire could be better though. It''s too ridged. If it had a little wave to it that would have complimented the surface curvature nicely.', '2008-03-05 19:08:40.000000', NULL, 1),
(4541641, 653974, 41337, '<td valign="top">Nice abstract. Took me a second to realize that''s a fork and spoon. I think you would be better served if you chose to use just one in your splash.</td>', 'Nice abstract. Took me a second to realize that''s a fork and spoon. I think you would be better served if you chose to use just one in your splash.', '2008-03-05 19:11:46.000000', NULL, 1),
(4541644, 654534, 77196, '<td valign="top">Great concept. Great composition. Wrong angle - reflections in silverware just aren''t right &amp; silverware looks dirty.</td>', 'Great concept. Great composition. Wrong angle - reflections in silverware just aren''t right & silverware looks dirty.', '2008-03-05 19:12:18.000000', NULL, 1),
(4541648, 654512, 41337, '<td valign="top">Beautiful lighting. Great contrast between the ridged fork and it''s softer curvy shadow. Well done!</td>', 'Beautiful lighting. Great contrast between the ridged fork and it''s softer curvy shadow. Well done!', '2008-03-05 19:13:36.000000', NULL, 1),
(4541655, 654203, 41337, '<td valign="top">Very pretty. Great control with the light!</td>', 'Very pretty. Great control with the light!', '2008-03-05 19:15:20.000000', NULL, 1),
(4541662, 652581, 77196, '<td valign="top">This just doesn''t cut it. The knives are not distinct enough.</td>', 'This just doesn''t cut it. The knives are not distinct enough.', '2008-03-05 19:16:37.000000', NULL, 1),
(4541670, 654295, 41337, '<td valign="top">Interesting shot. It''s chaotic yet orderly at the same time.</td>', 'Interesting shot. It''s chaotic yet orderly at the same time.', '2008-03-05 19:18:20.000000', NULL, 1),
(4541702, 654522, 41337, '<td valign="top">The choice in DOF doesn''t really work for me but not a bad shot.</td>', 'The choice in DOF doesn''t really work for me but not a bad shot.', '2008-03-05 19:32:15.000000', NULL, 1),
(4541711, 654041, 41337, '<td valign="top">Good lighting. The cough drops (or marbles?) was a nice touch. The only issue I have with the shot is it looks terribly over sharpened or maybe those jaggies are due to how you resized it? Other than that it''s a good shot.</td>', 'Good lighting. The cough drops (or marbles?) was a nice touch. The only issue I have with the shot is it looks terribly over sharpened or maybe those jaggies are due to how you resized it? Other than that it''s a good shot.', '2008-03-05 19:37:33.000000', NULL, 1),
(4541716, 653656, 41337, '<td valign="top">Beautifully arranged and the lighting magnificent!</td>', 'Beautifully arranged and the lighting magnificent!', '2008-03-05 19:39:45.000000', NULL, 1),
(4541878, 654259, 65234, '<td valign="top">::groan::  Nice bokeh on the foreground highlights.</td>', '::groan::  Nice bokeh on the foreground highlights.', '2008-03-05 21:00:23.000000', NULL, 1),
(4541883, 654751, 65234, '<td valign="top">Nice subjects and lovely background to set them off.  Seems rather OOF to me, though, and I don''t feel that enhances the image.</td>', 'Nice subjects and lovely background to set them off.  Seems rather OOF to me, though, and I don''t feel that enhances the image.', '2008-03-05 21:01:37.000000', NULL, 1),
(4541884, 654478, 65234, '<td valign="top">Nice composition.</td>', 'Nice composition.', '2008-03-05 21:02:13.000000', NULL, 1),
(4541889, 654363, 65234, '<td valign="top">Great idea; water adds dynamism to a normally static subject.</td>', 'Great idea; water adds dynamism to a normally static subject.', '2008-03-05 21:03:57.000000', NULL, 1),
(4541890, 654790, 65234, '<td valign="top">Nicely anthropomorphized.</td>', 'Nicely anthropomorphized.', '2008-03-05 21:04:23.000000', NULL, 1),
(4541891, 653731, 65234, '<td valign="top">That is one well-used knife.  Good thing for the ladybug its probably not too sharp.  She adds nice color to this.</td>', 'That is one well-used knife.  Good thing for the ladybug its probably not too sharp.  She adds nice color to this.', '2008-03-05 21:05:08.000000', NULL, 1),
(4541893, 654052, 65234, '<td valign="top">Nice choice of background for these.</td>', 'Nice choice of background for these.', '2008-03-05 21:05:49.000000', NULL, 1),
(4541900, 654546, 65234, '<td valign="top">Colorful ... doesn''t look terribly appetizing to me but it doesn''t need to.</td>', 'Colorful ... doesn''t look terribly appetizing to me but it doesn''t need to.', '2008-03-05 21:08:12.000000', NULL, 1),
(4541903, 654054, 65234, '<td valign="top">Deformed silverware!  Reminds me of some sort of gymnastic contortions.</td>', 'Deformed silverware!  Reminds me of some sort of gymnastic contortions.', '2008-03-05 21:09:22.000000', NULL, 1),
(4541906, 653850, 65234, '<td valign="top">Quite an elaborate spoon, but the bowl looks even more interesting.</td>', 'Quite an elaborate spoon, but the bowl looks even more interesting.', '2008-03-05 21:10:18.000000', NULL, 1),
(4541910, 652733, 65234, '<td valign="top">Nice effect.</td>', 'Nice effect.', '2008-03-05 21:11:11.000000', NULL, 1),
(4541926, 654050, 65234, '<td valign="top">PEEPS :-)))  Sorry; got a little overexcited there.  They do make a colorful addition to the silverware.</td>', 'PEEPS :-)))  Sorry; got a little overexcited there.  They do make a colorful addition to the silverware.', '2008-03-05 21:16:27.000000', NULL, 1),
(4541929, 652842, 65234, '<td valign="top">Pretty cool effect.</td>', 'Pretty cool effect.', '2008-03-05 21:16:55.000000', NULL, 1),
(4541932, 654512, 65234, '<td valign="top">Very nice combination of shapes and textures.</td>', 'Very nice combination of shapes and textures.', '2008-03-05 21:17:33.000000', NULL, 1),
(4541935, 654399, 65234, '<td valign="top">Nice composition and reflections.</td>', 'Nice composition and reflections.', '2008-03-05 21:18:28.000000', NULL, 1),
(4541937, 654045, 65234, '<td valign="top">Looks like a nice old-fashioned design.  Good coomposition to show it off.</td>', 'Looks like a nice old-fashioned design.  Good coomposition to show it off.', '2008-03-05 21:18:55.000000', NULL, 1),
(4541939, 654041, 65234, '<td valign="top">Very pretty arrangement.</td>', 'Very pretty arrangement.', '2008-03-05 21:19:41.000000', NULL, 1),
(4541942, 654462, 65234, '<td valign="top">You didn''t save any for me!  Bummer :-(</td>', 'You didn''t save any for me!  Bummer :-(', '2008-03-05 21:20:13.000000', NULL, 1),
(4541950, 654453, 65234, '<td valign="top">I''ve looked but I can''t seem to find any silverware or anything that looks like it.  Unusual to see pottery in the straw (and straw in the pottery) so the image definitely gets my attention, but not a great fit for the challenge IMO.</td>', 'I''ve looked but I can''t seem to find any silverware or anything that looks like it.  Unusual to see pottery in the straw (and straw in the pottery) so the image definitely gets my attention, but not a great fit for the challenge IMO.', '2008-03-05 21:23:52.000000', NULL, 1),
(4541952, 653225, 65234, '<td valign="top">Cute idea; lighting is rather harsh.</td>', 'Cute idea; lighting is rather harsh.', '2008-03-05 21:24:24.000000', NULL, 1),
(4541955, 653336, 65234, '<td valign="top">So that''s what a teaspoon of chaos looks like!  Fun shot.</td>', 'So that''s what a teaspoon of chaos looks like!  Fun shot.', '2008-03-05 21:25:23.000000', NULL, 1),
(4541959, 654698, 65234, '<td valign="top">That''s an awful lot of silverware for a snack.  You must have help doing the dishes ;-)  And ... I really feel the need to swap the forks with the knives/spoons so they''re on the correct side of the plate!!</td>', 'That''s an awful lot of silverware for a snack.  You must have help doing the dishes ;-)  And ... I really feel the need to swap the forks with the knives/spoons so they''re on the correct side of the plate!!', '2008-03-05 21:27:53.000000', NULL, 1),
(4541961, 654461, 65234, '<td valign="top">Quite an elaborate pattern.</td>', 'Quite an elaborate pattern.', '2008-03-05 21:29:03.000000', NULL, 1),
(4541966, 654621, 65234, '<td valign="top">The smile is blatant in the thumbnail; less so in this view.  Still a cute idea.</td>', 'The smile is blatant in the thumbnail; less so in this view.  Still a cute idea.', '2008-03-05 21:29:51.000000', NULL, 1),
(4541968, 654739, 65234, '<td valign="top">I love a good literal interpretation of a cliche :-)</td>', 'I love a good literal interpretation of a cliche :-)', '2008-03-05 21:30:37.000000', NULL, 1),
(4541976, 654532, 65234, '<td valign="top">Awesome twist ;-)</td>', 'Awesome twist ;-)', '2008-03-05 21:34:29.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
