(4544164, 654698, 80807, '<td valign="top">Beautiful colors, shadows and lighting. It could have done without the food, yet I do not find it distracting.  Well done.</td>', 'Beautiful colors, shadows and lighting. It could have done without the food, yet I do not find it distracting.  Well done.', '2008-03-06 20:53:22.000000', NULL, 1),
(4544173, 654373, 69246, '<td valign="top">3 things for improvement: Color cast, focus, and lighing.</td>', '3 things for improvement: Color cast, focus, and lighing.', '2008-03-06 20:54:51.000000', NULL, 1),
