(4549391, 654533, 53509, '<td valign="top">Love the perspective. Somehow the handle of the fork looks weirdly curved, and it keeps bugging me.</td>', 'Love the perspective. Somehow the handle of the fork looks weirdly curved, and it keeps bugging me.', '2008-03-08 23:49:09.000000', NULL, 1),
(4549393, 654781, 53509, '<td valign="top">In my opinion, there''s jut not enough in foucs here to keep my attention.</td>', 'In my opinion, there''s jut not enough in foucs here to keep my attention.', '2008-03-08 23:49:32.000000', NULL, 1),
(4549394, 654508, 53509, '<td valign="top">Creative - I like it..</td>', 'Creative - I like it..', '2008-03-08 23:50:05.000000', NULL, 1),
(4549396, 653751, 53509, '<td valign="top">A nice old-time feel.</td>', 'A nice old-time feel.', '2008-03-08 23:50:28.000000', NULL, 1),
(4549398, 654696, 53509, '<td valign="top">I like the motion capture here. Perhaps I''m being picky, but the sugar does seem to be the main subject, not the spoon.</td>', 'I like the motion capture here. Perhaps I''m being picky, but the sugar does seem to be the main subject, not the spoon.', '2008-03-08 23:51:01.000000', NULL, 1),
(4549399, 654773, 53509, '<td valign="top">I don''t think this background really helps much. There''s also a lot happening in the spoon reflection, but it doesn''t add to the composition.</td>', 'I don''t think this background really helps much. There''s also a lot happening in the spoon reflection, but it doesn''t add to the composition.', '2008-03-08 23:51:37.000000', NULL, 1),
(4549402, 653091, 53509, '<td valign="top">Sharp and interesting. The spoon doesn''t really seem central here - with the really sharp reflection, it almost blends into the background.</td>', 'Sharp and interesting. The spoon doesn''t really seem central here - with the really sharp reflection, it almost blends into the background.', '2008-03-08 23:52:15.000000', NULL, 1),
(4549403, 652909, 53509, '<td valign="top">I like this idea, I just wish the spoon didn''t have so many extraneous and distracting reflections in the head.</td>', 'I like this idea, I just wish the spoon didn''t have so many extraneous and distracting reflections in the head.', '2008-03-08 23:52:50.000000', NULL, 1),
(4549405, 653503, 53509, '<td valign="top">Beautiful light and lines. Love it!</td>', 'Beautiful light and lines. Love it!', '2008-03-08 23:53:07.000000', NULL, 1),
(4549421, 654099, 53509, '<td valign="top">I wish there wasn''t an orange highlight on the left of the spoon. I like the light on the flower.</td>', 'I wish there wasn''t an orange highlight on the left of the spoon. I like the light on the flower.', '2008-03-09 00:08:02.000000', NULL, 1),
(4549422, 654684, 53509, '<td valign="top">The surface is too busy for me - it competes with the spoons.</td>', 'The surface is too busy for me - it competes with the spoons.', '2008-03-09 00:08:44.000000', NULL, 1),
(4549424, 652234, 53509, '<td valign="top">An ironic title. My eye wanders a little too much in this composition.</td>', 'An ironic title. My eye wanders a little too much in this composition.', '2008-03-09 00:09:23.000000', NULL, 1),
(4549427, 654698, 53509, '<td valign="top">I like the play of light in the photo. Silver doesn''t really seem to be the central focus though.</td>', 'I like the play of light in the photo. Silver doesn''t really seem to be the central focus though.', '2008-03-09 00:10:03.000000', NULL, 1),
(4549428, 654480, 53509, '<td valign="top">The lighting drops far too much into the background and the fork is not the emphasis.</td>', 'The lighting drops far too much into the background and the fork is not the emphasis.', '2008-03-09 00:10:29.000000', NULL, 1),
(4549429, 654695, 53509, '<td valign="top">I like this arrangement, but there needs to be further work on getting rid of the distracting reflections in the spoons.</td>', 'I like this arrangement, but there needs to be further work on getting rid of the distracting reflections in the spoons.', '2008-03-09 00:11:01.000000', NULL, 1),
(4549431, 654531, 53509, '<td valign="top">Ha ha... neat idea and a sharp road picture.</td>', 'Ha ha... neat idea and a sharp road picture.', '2008-03-09 00:11:25.000000', NULL, 1),
(4549433, 654327, 53509, '<td valign="top">Too much of the silverware fades into the black and there are distracting reflections on many items.</td>', 'Too much of the silverware fades into the black and there are distracting reflections on many items.', '2008-03-09 00:11:53.000000', NULL, 1),
(4549434, 654209, 53509, '<td valign="top">I like this composition and the light. I wonder if the frame adds to the pictures or cropping tighter might have helped.</td>', 'I like this composition and the light. I wonder if the frame adds to the pictures or cropping tighter might have helped.', '2008-03-09 00:12:27.000000', NULL, 1),
(4549435, 653624, 53509, '<td valign="top">I don''t much care for the coloured light on the utensils.</td>', 'I don''t much care for the coloured light on the utensils.', '2008-03-09 00:13:01.000000', NULL, 1),
(4549436, 653760, 53509, '<td valign="top">The knife needs to be more prominent, and the background seems uneven and uninteresting.</td>', 'The knife needs to be more prominent, and the background seems uneven and uninteresting.', '2008-03-09 00:13:32.000000', NULL, 1),
(4549438, 653974, 53509, '<td valign="top">I love the movement!</td>', 'I love the movement!', '2008-03-09 00:13:49.000000', NULL, 1),
