(4552416, 654057, 48963, '<td valign="top">I love the oversize spoon and the direct gaze of her eyes.</td>', 'I love the oversize spoon and the direct gaze of her eyes.', '2008-03-10 14:03:11.000000', NULL, 1),
(4552421, 654760, 48963, '<td valign="top">Nicely done, I like the lighting, clarity and composition. I also love the silverware itself.</td>', 'Nicely done, I like the lighting, clarity and composition. I also love the silverware itself.', '2008-03-10 14:04:46.000000', NULL, 1),
(4552426, 654480, 48963, '<td valign="top">The lighting is kind of harsh here from the on camera flash.</td>', 'The lighting is kind of harsh here from the on camera flash.', '2008-03-10 14:06:31.000000', NULL, 1),
(4552427, 654652, 48963, '<td valign="top">I like the framing you have as well as the selective darkening of the green background. Nice amount of DOF too.</td>', 'I like the framing you have as well as the selective darkening of the green background. Nice amount of DOF too.', '2008-03-10 14:07:48.000000', NULL, 1),
(4552431, 654560, 48963, '<td valign="top">a nice change of pace from all that metal!</td>', 'a nice change of pace from all that metal!', '2008-03-10 14:09:20.000000', NULL, 1),
(4552435, 652354, 48963, '<td valign="top">interesting shot. I think it would''ve benefitted from not using the on camera flash though. The shadows spoil it a little for me.</td>', 'interesting shot. I think it would''ve benefitted from not using the on camera flash though. The shadows spoil it a little for me.', '2008-03-10 14:10:43.000000', NULL, 1),
(4552440, 654698, 48963, '<td valign="top">Fancy place setting for a midnight snack! :) Nicely done, but I''m not sure what it is on the plate. Kind of looks like a raw egg on a small piece of buttered bread.</td>', 'Fancy place setting for a midnight snack! :) Nicely done, but I''m not sure what it is on the plate. Kind of looks like a raw egg on a small piece of buttered bread.', '2008-03-10 14:13:20.000000', NULL, 1),
(4552446, 653913, 48963, '<td valign="top">I suggest a larger photo - would help your score I''m sure.</td>', 'I suggest a larger photo - would help your score I''m sure.', '2008-03-10 14:14:58.000000', NULL, 1),
(4552448, 654531, 48963, '<td valign="top">hahahahah. made me laugh, thanks ;)  plus, it''s actually a nice photo.</td>', 'hahahahah. made me laugh, thanks ;)  plus, it''s actually a nice photo.', '2008-03-10 14:15:55.000000', NULL, 1),
(4552449, 654742, 48963, '<td valign="top">Love it! Nice fresh idea.</td>', 'Love it! Nice fresh idea.', '2008-03-10 14:16:30.000000', NULL, 1),
(4552510, 653476, 84656, '<td valign="top">practical but gross ;)</td>', 'practical but gross ;)', '2008-03-10 14:46:40.000000', NULL, 1),
