(4556296, 654719, 88352, '<td valign="top">Love the antique look of everything in the photo, it goes together very well.</td>', 'Love the antique look of everything in the photo, it goes together very well.', '2008-03-11 22:29:47.000000', NULL, 1),
(4556297, 652909, 61961, '<td valign="top">Very cool.  I''ll be back later to bump this up. :-)</td>', 'Very cool.  I''ll be back later to bump this up. :-)', '2008-03-11 22:29:49.000000', NULL, 1),
