(4556305, 654685, 88352, '<td valign="top">Silver chopsticks... awesome!!</td>', 'Silver chopsticks... awesome!!', '2008-03-11 22:32:24.000000', NULL, 1),
(4556307, 654560, 88352, '<td valign="top">My eye is drawn through the photo well with these, and I can''t deicde if they are face down or face up!  At first glance it doesn''t seem like much, but it is very interesting to look at for a while.</td>', 'My eye is drawn through the photo well with these, and I can''t deicde if they are face down or face up!  At first glance it doesn''t seem like much, but it is very interesting to look at for a while.', '2008-03-11 22:33:36.000000', NULL, 1),
(4556308, 653913, 88352, '<td valign="top">Too small to tell, needs to be larger to really get what is going on here...</td>', 'Too small to tell, needs to be larger to really get what is going on here...', '2008-03-11 22:33:58.000000', NULL, 1),
(4556309, 654498, 88352, '<td valign="top">Ok, I''m not a man, but that knife looks to be in a painful place... ;)  I like the composition, but seems a little dull like nothing else is going on.</td>', 'Ok, I''m not a man, but that knife looks to be in a painful place... ;)  I like the composition, but seems a little dull like nothing else is going on.', '2008-03-11 22:35:03.000000', NULL, 1),
(4556312, 654453, 61961, '<td valign="top">I wonder if there is a language issue here, since this isn''t "silverware" -- however, interesting image.</td>', 'I wonder if there is a language issue here, since this isn''t "silverware" -- however, interesting image.', '2008-03-11 22:35:48.000000', NULL, 1),
(4556317, 654603, 61961, '<td valign="top">I can''t put my finger on why, but I keep coming back to this photo.  I love the shallow DOF and the professional shine.</td>', 'I can''t put my finger on why, but I keep coming back to this photo.  I love the shallow DOF and the professional shine.', '2008-03-11 22:37:38.000000', NULL, 1),
(4556319, 654218, 88352, '<td valign="top">I''m not trying to sound mean, but the subject of this challenge is silverware and although there is silverware in your photo, you have made the main subject a pear; The silverware could disappear and the meaning of the photo wouldn''t change...</td>', 'I''m not trying to sound mean, but the subject of this challenge is silverware and although there is silverware in your photo, you have made the main subject a pear; The silverware could disappear and the meaning of the photo wouldn''t change...', '2008-03-11 22:37:47.000000', NULL, 1),
(4556326, 654687, 88352, '<td valign="top">The sepia tone works great here!  makes the silverware seem alive...</td>', 'The sepia tone works great here!  makes the silverware seem alive...', '2008-03-11 22:39:50.000000', NULL, 1),
(4556332, 654268, 88352, '<td valign="top">I actually tried this, and couldn''t get it to work!  Very nicely done...</td>', 'I actually tried this, and couldn''t get it to work!  Very nicely done...', '2008-03-11 22:41:05.000000', NULL, 1),
(4556334, 654373, 88352, '<td valign="top">HAHAHA!  I love it.  And we''ve all seen those packets....</td>', 'HAHAHA!  I love it.  And we''ve all seen those packets....', '2008-03-11 22:41:38.000000', NULL, 1),
(4556423, 654659, 90495, '<td valign="top">Colourful idea, well executed.</td>', 'Colourful idea, well executed.', '2008-03-11 23:19:49.000000', NULL, 1),
(4556430, 654698, 90495, '<td valign="top">Nicely setup shot.  Colours are good. The right napkin is a little too much to the left and the right candle is higher than the other one. I would''ve used a fill light for the top 3 utensils or some other way to brighten them up. Overall great shot. Border works for me. 8.5</td>', 'Nicely setup shot.  Colours are good. The right napkin is a little too much to the left and the right candle is higher than the other one. I would''ve used a fill light for the top 3 utensils or some other way to brighten them up. Overall great shot. Border works for me. 8.5', '2008-03-11 23:24:03.000000', NULL, 1),
(4556431, 654505, 90495, '<td valign="top">Nice touch with the mint leaves. Simple yet beautiful on the eyes. GJ.</td>', 'Nice touch with the mint leaves. Simple yet beautiful on the eyes. GJ.', '2008-03-11 23:25:21.000000', NULL, 1);
