INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4565948, 654045, 56002, '<td valign="top">I have returned... to cherish this image.  It''s so wrenchingly beautiful.</td>', 'I have returned... to cherish this image.  It''s so wrenchingly beautiful.', '2008-03-15 19:22:45.000000', NULL, 0),
(4565950, 654317, 53964, '<td valign="top">Just one question :)<br/>Did you plan the spacing to make the illusion of white spoons, or was it coincidence?  (can''t believe it wasn''t planned... it''s just TOO good! :D )</td>', 'Just one question :)Did you plan the spacing to make the illusion of white spoons, or was it coincidence?  (can''t believe it wasn''t planned... it''s just TOO good! :D )', '2008-03-15 19:23:58.000000', NULL, 0),
(4567095, 654317, 48228, '<td valign="top">Awesome image and so pleased you received the Blue.....</td>', 'Awesome image and so pleased you received the Blue.....', '2008-03-16 09:25:00.000000', NULL, 0),
(4567427, 654317, 87278, '<td valign="top">Reminds me of Wordsworth: Making common things look uncommon. A very nice interpretation of a daily used article. Congrats 4 the BR.</td>', 'Reminds me of Wordsworth: Making common things look uncommon. A very nice interpretation of a daily used article. Congrats 4 the BR.', '2008-03-16 13:04:05.000000', NULL, 0),
(4568174, 654317, 7810, '<td valign="top">Love the line of this shot  love the contrast. Glad it ribboned ...Congrats!!!<br/>The simplest shot sometimes is all you need.    btw Welcome to the site.<br/> <br/>Coley</td>', 'Love the line of this shot  love the contrast. Glad it ribboned ...Congrats!!!The simplest shot sometimes is all you need.    btw Welcome to the site. Coley', '2008-03-16 21:47:18.000000', NULL, 0),
(4568221, 654317, 60195, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by BeeCee:</b></div><hr/><i> Just one question :)<br/>Did you plan the spacing to make the illusion of white spoons, or was it coincidence?  (can''t believe it wasn''t planned... it''s just TOO good! :D ) </i></td></tr></table> <br/> <br/>That is just <b>far too cool</b>, JR!  From the thread that BeeCee started <a href="//www.dpchallenge.com/forum.php?action=read&amp;FORUM_THREAD_ID=754932" rel="nofollow" target="_blank">here</a>.  Kudos!  Well deserving of the Blue.<br/> <br/>You might consider adding that to the image Description above - I''m sure that most people missed it... and it''s a key element.</td>', 'Originally posted by BeeCee: Just one question :)Did you plan the spacing to make the illusion of white spoons, or was it coincidence?  (can''t believe it wasn''t planned... it''s just TOO good! :D )   That is just far too cool, JR!  From the thread that BeeCee started here.  Kudos!  Well deserving of the Blue. You might consider adding that to the image Description above - I''m sure that most people missed it... and it''s a key element.', '2008-03-16 22:04:27.000000', NULL, 0),
(4568382, 653336, 24454, '<td valign="top">Aimee, this is so great!   I thought it might be Irene''s with how clean and flawlessly executed it is.   Congratulations!!<br/> <br/></td>', 'Aimee, this is so great!   I thought it might be Irene''s with how clean and flawlessly executed it is.   Congratulations!! ', '2008-03-16 23:51:48.000000', NULL, 0),
(4568758, 653336, 60195, '<td valign="top">Congrats on the Yellow, Aimee (your turn to gloat around the house for a while!)  ;O)<br/>Neat trick with the water.  Well done!</td>', 'Congrats on the Yellow, Aimee (your turn to gloat around the house for a while!)  ;O)Neat trick with the water.  Well done!', '2008-03-17 05:44:26.000000', NULL, 0),
(4568760, 654317, 90495, '<td valign="top">Thanks for that. I hadn''t seen the thread.</td>', 'Thanks for that. I hadn''t seen the thread.', '2008-03-17 05:52:48.000000', NULL, 0),
(4569270, 654045, 69388, '<td valign="top">This is so beautiful! There''s a feeling of nostalgia...or maybe it''s just me.</td>', 'This is so beautiful! There''s a feeling of nostalgia...or maybe it''s just me.', '2008-03-17 12:00:01.000000', NULL, 0),
(4569614, 654045, 67697, '<td valign="top">This is sooo pretty!  I love the soft lighting.  It looks like such a soft and quiet moment - perfect for enjoying tea.  It''s kind of cool that the silverware pattern almost matches the cup pattern.  I love that selective focus too.</td>', 'This is sooo pretty!  I love the soft lighting.  It looks like such a soft and quiet moment - perfect for enjoying tea.  It''s kind of cool that the silverware pattern almost matches the cup pattern.  I love that selective focus too.', '2008-03-17 15:49:46.000000', NULL, 0),
(4569967, 654334, 14476, '<td valign="top">oh, congratulations, Jeff.  I really liked this image all the way and thought it might be a lot closer to the front page.  <br/> <br/>Not to worry!  you received an Award That Counts!</td>', 'oh, congratulations, Jeff.  I really liked this image all the way and thought it might be a lot closer to the front page.   Not to worry!  you received an Award That Counts!', '2008-03-17 19:27:21.000000', NULL, 0),
(4571827, 654317, 59029, '<td valign="top">The KISS principle at its best.  Well done and welcome to the jungl...er, the site...</td>', 'The KISS principle at its best.  Well done and welcome to the jungl...er, the site...', '2008-03-18 17:46:46.000000', NULL, 0),
(4572474, 653336, 4793, '<td valign="top">Congratulations a very nice shot</td>', 'Congratulations a very nice shot', '2008-03-18 23:39:18.000000', NULL, 0),
(4575607, 653803, 89424, '<td valign="top">The point of the picture was to have the plastic spoon (with the drawn tear on it) to be awkwardly standing out of the photograph of the two other spoons as if the plastic one was an outcast...<br/>thanks.</td>', 'The point of the picture was to have the plastic spoon (with the drawn tear on it) to be awkwardly standing out of the photograph of the two other spoons as if the plastic one was an outcast...thanks.', '2008-03-19 22:43:18.000000', NULL, 0),
(4582640, 652431, 30982, '<td valign="top">Simple, elegant, well-executed, and a funky-looking ribbon thingie...</td>', 'Simple, elegant, well-executed, and a funky-looking ribbon thingie...', '2008-03-24 06:18:16.000000', NULL, 0),
(4582951, 654538, 52115, '<td valign="top">Maybe a yellow-gold spoon on the right would be interesting.</td>', 'Maybe a yellow-gold spoon on the right would be interesting.', '2008-03-24 09:44:50.000000', NULL, 0),
(4586063, 654500, 23002, '<td valign="top">Very nice to see the contrast of the silverware against the faux fur.</td>', 'Very nice to see the contrast of the silverware against the faux fur.', '2008-03-25 15:46:10.000000', NULL, 0),
(4586080, 653460, 23002, '<td valign="top">Love the spoon and it''s shadow/reflection, however I think it might have been more effective to just shoot it, and leave the top part out.</td>', 'Love the spoon and it''s shadow/reflection, however I think it might have been more effective to just shoot it, and leave the top part out.', '2008-03-25 15:47:43.000000', NULL, 0),
(4586093, 654762, 23002, '<td valign="top">Your woody is certainly not shy!</td>', 'Your woody is certainly not shy!', '2008-03-25 15:49:27.000000', NULL, 0),
(4586113, 654334, 23002, '<td valign="top">Wow.  I love this shot!  I think I like the out take you provided a bit more, but both are superb. :)  The thought behind it, the lighting, the composition...it works.</td>', 'Wow.  I love this shot!  I think I like the out take you provided a bit more, but both are superb. :)  The thought behind it, the lighting, the composition...it works.', '2008-03-25 15:51:53.000000', NULL, 0),
(4586127, 654045, 23002, '<td valign="top">Great shot!  It has a wonderful elegance to it.  your choice of a shallow DOF works very well because it keeps it from becoming "busy" while still getting the point across.  Did you point your pinky finger in the air while drinking the tea? :)</td>', 'Great shot!  It has a wonderful elegance to it.  your choice of a shallow DOF works very well because it keeps it from becoming "busy" while still getting the point across.  Did you point your pinky finger in the air while drinking the tea? :)', '2008-03-25 15:54:26.000000', NULL, 0),
(4586133, 654054, 23002, '<td valign="top">The contortionists of silverware!  I was amazed while shooting my own shot, and while looking at everyone elses, that in many cases it is hard to tell which way the spoon or fork is sitting.  (pointing up or down) It looks like both of these are facing up.  However if you were to look at just the end of the spoon it would be hard to tell...</td>', 'The contortionists of silverware!  I was amazed while shooting my own shot, and while looking at everyone elses, that in many cases it is hard to tell which way the spoon or fork is sitting.  (pointing up or down) It looks like both of these are facing up.  However if you were to look at just the end of the spoon it would be hard to tell...', '2008-03-25 15:57:04.000000', NULL, 0),
(4586137, 654050, 23002, '<td valign="top">I like how you were able to squeeze in some colour into this challenge.  Since I am viewing this after the marshmellow peeps challenge, I wonder if that was the fate of these little guys...</td>', 'I like how you were able to squeeze in some colour into this challenge.  Since I am viewing this after the marshmellow peeps challenge, I wonder if that was the fate of these little guys...', '2008-03-25 15:59:07.000000', NULL, 0),
(4591959, 654554, 91944, '<td valign="top">Very interesting. Very creative. Sharp image. Can you rate a photo that is not in a challange, I am new to this. but if i can rate it I give it a 9.</td>', 'Very interesting. Very creative. Sharp image. Can you rate a photo that is not in a challange, I am new to this. but if i can rate it I give it a 9.', '2008-03-27 17:08:15.000000', NULL, 0),
(4592016, 654045, 51793, '<td valign="top">Hey there just going through some challenges and thought this was a good picture. I really think that it should have done much better. The focus on the spoon is very sharp and makes the whole picture stand out. Amazing job on this really. Great work by you as always. Keep it up.</td>', 'Hey there just going through some challenges and thought this was a good picture. I really think that it should have done much better. The focus on the spoon is very sharp and makes the whole picture stand out. Amazing job on this really. Great work by you as always. Keep it up.', '2008-03-27 17:39:16.000000', NULL, 0),
(4592063, 654045, 40718, '<td valign="top">This is another one that might go with some image grain.  You''d keep it off the spoon which is nicely clear, but put it in the open spaces and blurred background.  The sepia tone already gives it that old look.  Grain would just add to it IMO.</td>', 'This is another one that might go with some image grain.  You''d keep it off the spoon which is nicely clear, but put it in the open spaces and blurred background.  The sepia tone already gives it that old look.  Grain would just add to it IMO.', '2008-03-27 17:59:31.000000', NULL, 0),
(4592111, 654713, 68586, '<td valign="top">I''ve got to try doing one of these ''splash'' shot''s sometime - I suspect they are harder than they look  :- )<br/> <br/>Nice capture, perhaps cropped in alittle too tight at the top, and maybe lacking some nice punchy colours.<br/> <br/>Good lighting and focus though.<br/><br/><i>Message edited by author 2008-03-27 18:17:32.</i></td>', 'I''ve got to try doing one of these ''splash'' shot''s sometime - I suspect they are harder than they look  :- ) Nice capture, perhaps cropped in alittle too tight at the top, and maybe lacking some nice punchy colours. Good lighting and focus though.', '2008-03-27 18:17:06.000000', '2008-03-27 18:17:32.000000', 0),
(4592140, 654045, 66524, '<td valign="top">Perhaps it''s my own sentiment toward these kinds of things, but I adore this shot!</td>', 'Perhaps it''s my own sentiment toward these kinds of things, but I adore this shot!', '2008-03-27 18:36:45.000000', NULL, 0),
(4593118, 654762, 50641, '<td valign="top">This is funny! Great idea and I like how there is also the suggestion of narcissim as he looks at his reflection in her face.</td>', 'This is funny! Great idea and I like how there is also the suggestion of narcissim as he looks at his reflection in her face.', '2008-03-28 08:56:21.000000', NULL, 0),
(4593287, 652909, 91944, '<td valign="top">Very creative and funny. Shot could have been better, like you said maybe a new spoon and different background.</td>', 'Very creative and funny. Shot could have been better, like you said maybe a new spoon and different background.', '2008-03-28 10:07:02.000000', NULL, 0),
(4593291, 654669, 91944, '<td valign="top">I would like to see this with more zoom. Great pictures.</td>', 'I would like to see this with more zoom. Great pictures.', '2008-03-28 10:09:58.000000', NULL, 0),
(4593937, 653731, 30982, '<td valign="top">I don''t know - I think the chaotic scratches add a sense of texture and depth.  Were they all horizontal and evenly spaced it might not be as appealing.  You have a great series of ladybug prints you can market - I suspect that''s your plan?</td>', 'I don''t know - I think the chaotic scratches add a sense of texture and depth.  Were they all horizontal and evenly spaced it might not be as appealing.  You have a great series of ladybug prints you can market - I suspect that''s your plan?', '2008-03-28 15:29:35.000000', NULL, 0),
(4594440, 653336, 66524, '<td valign="top">Congratulations on your ribbon!<br/>Very creative approach...keep giving the family secrets away!</td>', 'Congratulations on your ribbon!Very creative approach...keep giving the family secrets away!', '2008-03-28 19:28:27.000000', NULL, 0),
(4594449, 654045, 48227, '<td valign="top">How could I miss something like this! WOW, this is PERFECT.</td>', 'How could I miss something like this! WOW, this is PERFECT.', '2008-03-28 19:33:46.000000', NULL, 0),
